<template><div class="page-container"><div class="page-head"><div><h2 class="page-title">司南推广链</h2><p class="page-subtitle">创建后可直接带入 Meta 批量投放。</p></div><div><el-button @click="load">刷新</el-button><el-button type="primary" @click="openCreate">新增推广链</el-button></div></div><el-card shadow="never"><el-table :data="items" v-loading="loading"><el-table-column prop="promotion_name" label="推广链名称"/><el-table-column prop="drama_title" label="推广内容"/><el-table-column prop="chapter_title" label="跳转节点"/><el-table-column prop="ad_group" label="广告组"/><el-table-column prop="landing_url" label="推广链接" show-overflow-tooltip/><el-table-column label="操作"><template #default="{row}"><el-button link @click="goPublish(row)">去投放</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="visible" title="新增推广链" width="680px"><el-form :model="form" label-width="110px"><el-form-item label="推广应用" required><el-select v-model="form.real_app_id" filterable style="width:100%"><el-option v-for="a in apps" :key="a.id" :label="a.name" :value="a.id"/></el-select></el-form-item><el-form-item label="链接名称" required><el-input v-model="form.promotion_name"/></el-form-item><el-form-item label="内容体裁"><el-radio-group v-model="contentType"><el-radio-button label="SHORT_VIDEO">短剧</el-radio-button><el-radio-button label="COMIC">漫剧</el-radio-button></el-radio-group></el-form-item><el-form-item label="推广内容" required><el-select v-model="form.drama_id" filterable remote :remote-method="searchContent" :loading="contentLoading" style="width:100%" @change="loadChapters"><el-option v-for="d in dramas" :key="d.drama_id" :label="`${d.title||d.drama_title}（${d.drama_id}）`" :value="d.drama_id"/></el-select></el-form-item><el-form-item label="跳转节点" required><el-select v-model="form.chapter_id" style="width:100%"><el-option v-for="c in chapters" :key="c.chapter_id||c.id" :label="c.chapter_title||c.title||`第${c.sort_no}集`" :value="c.chapter_id||c.id"/></el-select></el-form-item><el-form-item label="回传规则"><el-select v-model="form.ad_convt_config_id" style="width:100%"><el-option v-for="r in rules" :key="r.id||r.ad_convt_config_id" :label="r.name||r.config_name" :value="r.id||r.ad_convt_config_id"/></el-select></el-form-item><el-form-item label="充值档位"><el-select v-model="form.recharge_tpl_id" style="width:100%"><el-option v-for="r in recharge" :key="r.id||r.recharge_tpl_id" :label="r.name||r.template_name" :value="r.id||r.recharge_tpl_id"/></el-select></el-form-item><el-form-item label="Pixel"><el-select v-model="form.pixel_id" style="width:100%"><el-option v-for="p in pixels" :key="p.id||p.pixel_id" :label="p.name||p.pixel_name" :value="p.id||p.pixel_id"/></el-select></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">创建推广链</el-button></template></el-dialog></div></template>
<script setup lang="ts">import{onMounted,reactive,ref,watch}from'vue';import{ElMessage}from'element-plus';import{useRouter}from'vue-router';import{sinanPromotionsApi}from'@/api/sinanPromotions';const router=useRouter(),items=ref<any[]>([]),loading=ref(false),visible=ref(false),saving=ref(false),contentLoading=ref(false),apps=ref<any[]>([]),dramas=ref<any[]>([]),chapters=ref<any[]>([]),rules=ref<any[]>([]),recharge=ref<any[]>([]),pixels=ref<any[]>([]),contentType=ref('SHORT_VIDEO');const form=reactive<any>({promotion_name:'',real_app_id:'',drama_id:'',chapter_id:'',media_channel:1,landing_type:1,pixel_id:'',ad_convt_config_id:'',recharge_tpl_id:'',price_strategy_source:1,client_os:0,turn_tag:1,delivery_goal:1,genre:4});async function load(){loading.value=true;try{const d=(await sinanPromotionsApi.list()).data;items.value=d.Promotions||d.items||[]}finally{loading.value=false}}async function openCreate(){Object.assign(form,{promotion_name:'',drama_id:'',chapter_id:'',pixel_id:'',ad_convt_config_id:'',recharge_tpl_id:'',price_strategy_source:1});visible.value=true;const[a,r]=await Promise.all([sinanPromotionsApi.apps(),sinanPromotionsApi.returnRules()]);apps.value=a.data.items||a.data||[];rules.value=r.data.items||r.data||[]}async function searchContent(q:string){if(!q)return;contentLoading.value=true;try{const d=(await sinanPromotionsApi.contentList({content_type:contentType.value,keyword:q})).data;dramas.value=d.items||[]}finally{contentLoading.value=false}}async function loadChapters(id:string){chapters.value=((await sinanPromotionsApi.chapters(id)).data.items||[]);const[r,p]=await Promise.all([sinanPromotionsApi.rechargeTemplates(form.real_app_id),sinanPromotionsApi.pixels(form.real_app_id)]);recharge.value=r.data.recharge_templates||[];pixels.value=p.data.pixel_list||[]}async function save(){saving.value=true;try{const d=await sinanPromotionsApi.create(form);ElMessage.success('推广链创建成功');visible.value=false;await load();const id=d.data?.promotion_id;if(id)goPublish({promotion_id:id})}finally{saving.value=false}}function goPublish(r:any){router.push({path:'/dashboard/batch-publish',query:{sinan_promotion_id:r.promotion_id}})}watch(contentType,()=>{dramas.value=[];chapters.value=[]});onMounted(load)</script>
